# Practice lecture exams for Veterinary Systems (Exam 10/16). Original questions written in the style of
# the 2024/2025 exams (Basel/Klimek) and Musch's exam setup (HR 7 · SV 6 · SVR 4 · a-vO2 2 · micro 3 ·
# exercise 6 · HF 6 · CV facts 5). Every question is unique across the 3 exams.
# Item: ('§', title)  or  (stem, options, [correct idx], why, sure, fig)   fig = figure key or None
from sys_practice_svg import ecg, six_lead, ap_vent, ap_node

def Q(stem, opts, ans, why='', sure=1, fig=None):
    return (stem, opts, ans if isinstance(ans, list) else [ans], why, sure, fig)

def TF(stem, truth, why='', sure=1, fig=None):
    return (stem + ' (True/False)', ['True', 'False'], [0 if truth else 1], why, sure, fig)

S = lambda t: ('§', t)
CLS = ['Class 0', 'Class 1', 'Class 2', 'Class 3', 'Class 4']
CH = ['Fast voltage-gated sodium channel (Nav1.5)', 'Hyperpolarization-activated, cyclic nucleotide-gated channel (HCN)',
      'Slow (L-type) calcium channel (Cav1.2)', 'Transient (T-type) calcium channel (Cav3.1)', 'Voltage-gated potassium channel (Kv)']

